import React from 'react';

import { IHiker } from '@apps/Hiking/@types/hiking.types';
import { showModal } from '@ui-kit/Modal';

import HikerSelector from './index';

export function selectHikerAsync(id_hiking: number, options = { withMe: false }): Promise<IHiker> {
  return new Promise((resolve) => {
    showModal({
      size: 'sm',
      title: 'Выбор участника',
      children: (closeHandler: () => void) => (
        <HikerSelector
          id_hiking={id_hiking}
          withMe={options.withMe}
          onSelect={(user) => {
            resolve(user);
            closeHandler();
          }}
        />
      ),
    });
  });
}
