/* eslint-disable @typescript-eslint/ban-ts-comment */
import React from 'react';

import { getHikingDataAsync } from '@apps/Hiking/@services/hiking.service';
import { IHiker } from '@apps/Hiking/@types/hiking.types';
import { err } from '@helpers/notificationHelper';
import PohAva from '@ui-kit/Ava';
import PohList from '@ui-kit/List';

import PageLoader from '../PageLoader';

interface IHikerSelectorProps {
  id_hiking: number;
  onSelect: (selectedHiker: IHiker) => void;
  withMe?: boolean;
}

const HikerSelector: React.FC<IHikerSelectorProps> = ({ id_hiking, onSelect, withMe = false }) => {
  const [hikers, setHikers] = React.useState<IHiker[]>([]);
  const [isLoading, setIsLoading] = React.useState(false);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        const hikingData = await getHikingDataAsync(id_hiking);

        // @ts-ignore
        const currentUser = +window?.user?.id;

        setHikers(hikingData.hikers.filter((x) => withMe || x.idUser !== currentUser));
      } finally {
        setIsLoading(false);
      }
    };

    init().catch(err);
  }, [id_hiking]);

  if (isLoading) {
    return <PageLoader />;
  }

  return (
    <PohList
      data={hikers.map((user) => ({
        key: user.idUser,
        content: (
          <>
            <PohAva src={user.photo['50']} alt={user.name} className="my-n2 ms-n2 me-2" />
            <strong title={user.positions.join('\n')}>
              {user.name} {user.surname}
            </strong>
          </>
        ),
        action: true,
        onClick: () => onSelect(user),
      }))}
    />
  );
};

export default HikerSelector;
